        replaceSidebar: typeof raw.replaceSidebar === 'boolean' ? raw.replaceSidebar : DEFAULT_CONFIG.replaceSidebar,
        replaceHero: typeof raw.replaceHero === 'boolean' ? raw.replaceHero : DEFAULT_CONFIG.replaceHero,
        hideHomeWhale: typeof raw.hideHomeWhale === 'boolean' ? raw.hideHomeWhale : DEFAULT_CONFIG.hideHomeWhale,
